.darma-loader-darma-b15-egg-fry-sizzle { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #fef9c3); width: var(--loader-size, 116px); height: calc(var(--loader-size, 116px) * .8); position: relative; }
.darma-loader-darma-b15-egg-fry-sizzle .darma-loader-darma-b15-egg-fry-sizzle__pan { position: absolute; left: 6%; top: 22%; width: 74%; height: 68%; border-radius: 50%; background: linear-gradient(#475569, #1e293b); }
.darma-loader-darma-b15-egg-fry-sizzle .darma-loader-darma-b15-egg-fry-sizzle__pan::after { content: ''; position: absolute; left: 92%; top: 40%; width: 42%; height: 16%; border-radius: 4px; background: #334155; }
.darma-loader-darma-b15-egg-fry-sizzle .darma-loader-darma-b15-egg-fry-sizzle__white { position: absolute; left: 16%; top: 32%; width: 54%; height: 48%; border-radius: 48% 52% 44% 56% / 52% 46% 54% 48%; background: var(--accent-2); animation: darma-loader-darma-b15-egg-fry-sizzle-egg-wobble calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b15-egg-fry-sizzle .darma-loader-darma-b15-egg-fry-sizzle__yolk { position: absolute; left: 33%; top: 44%; width: 22%; height: 24%; border-radius: 50%; background: radial-gradient(circle at 38% 34%, color-mix(in srgb, #fff 34%, var(--accent)), var(--accent)); animation: darma-loader-darma-b15-egg-fry-sizzle-egg-yolk calc(var(--loader-speed, 1s) * 1.6) ease-in-out infinite; }
.darma-loader-darma-b15-egg-fry-sizzle i { position: absolute; width: 7%; height: 7%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: darma-loader-darma-b15-egg-fry-sizzle-egg-sizzle calc(var(--loader-speed, 1s) * 1.2) ease-out infinite; }
.darma-loader-darma-b15-egg-fry-sizzle i:nth-of-type(1) { left: 22%; top: 26%; }
.darma-loader-darma-b15-egg-fry-sizzle i:nth-of-type(2) { left: 58%; top: 22%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b15-egg-fry-sizzle i:nth-of-type(3) { left: 40%; top: 18%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
@keyframes darma-loader-darma-b15-egg-fry-sizzle-egg-wobble { 0%, 100% { border-radius: 48% 52% 44% 56% / 52% 46% 54% 48%; transform: scale(1); } 50% { border-radius: 54% 46% 56% 44% / 46% 54% 46% 54%; transform: scale(1.03); } }
@keyframes darma-loader-darma-b15-egg-fry-sizzle-egg-yolk { 0%, 100% { transform: scale(1); } 50% { transform: scale(1.09); } }
@keyframes darma-loader-darma-b15-egg-fry-sizzle-egg-sizzle { 0% { opacity: 0; transform: translateY(0) scale(.4); } 30% { opacity: .9; } 100% { opacity: 0; transform: translateY(-120%) scale(1.1); } }

